#include <algorithm>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<double> perdidas{0.9, 0.4, 0.7, 0.2, 0.5};

    // Convierte cada perdida en una nota de 0 a 20
    std::transform(perdidas.begin(), perdidas.end(), perdidas.begin(),
                   [](double p) { return (1.0 - p) * 20.0; });

    const double suma = std::accumulate(perdidas.begin(), perdidas.end(), 0.0);
    const auto aprobados = std::count_if(perdidas.begin(), perdidas.end(),
                                         [](double nota) { return nota >= 11.0; });

    std::cout << std::fixed << std::setprecision(1);
    std::cout << "Media: " << suma / static_cast<double>(perdidas.size()) << '\n';
    std::cout << "Aprobados: " << aprobados << '\n';
    return 0;
}

#include <algorithm>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <string>
#include <vector>

struct Prediccion {
    std::string etiqueta;
    double probabilidad;
};

int main() {
    std::vector<Prediccion> salida{{"gato", 0.42}, {"perro", 0.51}, {"ave", 0.07}};

    std::sort(salida.begin(), salida.end(),
              [](const Prediccion& a, const Prediccion& b) {
                  return a.probabilidad > b.probabilidad;
              });

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "Clase: " << salida.front().etiqueta
              << " (" << salida.front().probabilidad << ")\n";

    const double total = std::accumulate(
        salida.begin(), salida.end(), 0.0,
        [](double acumulado, const Prediccion& p) {
            return acumulado + p.probabilidad;
        });

    std::cout << "Probabilidad total: " << total << '\n';
    return 0;
}

