#include <algorithm>
#include <iostream>
#include <vector>

int main() {
    std::vector<int> edades{23, 15, 42, 8, 31, 19};

    std::sort(edades.begin(), edades.end(),
              [](int a, int b) { return a > b; });

    const auto mayores = std::count_if(edades.begin(), edades.end(),
                                       [](int e) { return e >= 18; });

    for (int e : edades) {
        std::cout << e << ' ';
    }
    std::cout << "\nMayores de edad: " << mayores << '\n';
    return 0;
}

#include <algorithm>
#include <iomanip>
#include <iostream>
#include <numeric>
#include <vector>

int main() {
    std::vector<double> x{2.0, 4.0, 6.0, 8.0};

    const double min = *std::min_element(x.begin(), x.end());
    const double max = *std::max_element(x.begin(), x.end());

    std::transform(x.begin(), x.end(), x.begin(),
                   [min, max](double valor) {
                       return (valor - min) / (max - min);
                   });

    const double media = std::accumulate(x.begin(), x.end(), 0.0)
                         / static_cast<double>(x.size());

    std::cout << std::fixed << std::setprecision(3) << media << '\n';
    std::cout << std::distance(x.begin(), std::max_element(x.begin(), x.end()))
              << '\n';
    return 0;
}

